import { useEffect, useState, type KeyboardEvent } from 'react';
import { ThreadList } from './ThreadList';
import { fetchThreadPage, pageCount, type ThreadPage } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import styles from './Messages.module.css';

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es la pantalla, no un componente de presentación: carga la primera página de
 * hilos de `profile.orgId`, posee el estado de búsqueda y de página, y delega
 * el dibujado de la lista en `ThreadList`.
 *
 * - F-127/F-128: el aviso de error lleva `role="alert"` y enseña el error de
 *   verdad (code · message), nunca "[object Object]".
 * - F-137: `now?: Date | undefined` — bajo `exactOptionalPropertyTypes`, un
 *   `now?: Date` a secas rechazaría en compilación el `undefined` que puede
 *   llegar aquí. El default de `relativeTime` ya cubre el respaldo.
 * - F-139: el motivo de `Nuevo contacto` lleva `data-testid="directorio-scope"`.
 * - F-118: `onOpenThread` llega desde el shell pero MSG-02 no está en el
 *   alcance: se declara en la firma pública y se ignora a propósito.
 */

interface Props {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /** Cableado por el shell para MSG-02. Se recibe y no se usa (F-118). */
  onOpenThread?: (threadId: string) => void;
}

/** F-128: PostgREST rechaza con objetos planos `{ code, message }`, no siempre
 *  con un `Error`. El aviso tiene que enseñar ese detalle. */
function formatError(e: unknown): string {
  const base = 'No se pudieron cargar los hilos.';
  if (typeof e === 'string') return `${base} ${e}`;
  if (e instanceof Error) return `${base} ${e.message}`;
  if (e && typeof e === 'object') {
    const { code, message } = e as { code?: unknown; message?: unknown };
    const parts: string[] = [];
    if (typeof code === 'string') parts.push(code);
    if (typeof message === 'string') parts.push(message);
    if (parts.length > 0) return `${base} ${parts.join(' · ')}`;
  }
  return `${base} ${String(e)}`;
}

export function Messages({ profile, now }: Props) {
  const [searchInput, setSearchInput] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [data, setData] = useState<ThreadPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((p) => {
        if (active) setData(p);
      })
      .catch((e: unknown) => {
        if (active) setError(formatError(e));
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, [profile.orgId, search, page]);

  const applySearch = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      setSearch(searchInput.trim());
      setPage(1);
    }
  };

  const totalPages = data ? pageCount(data.total) : 1;

  return (
    <div className={styles.content}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está
        cifrado de extremo a extremo.
      </p>

      <div className={styles.e2eeBar}>
        <i className="ti ti-lock" aria-hidden="true" />
        E2EE activo · frase de seguridad en sesión · contenido descifrado localmente
      </div>

      <div className={styles.actionsBar}>
        <div className={styles.searchWrap}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            onKeyDown={applySearch}
          />
        </div>
        <button
          type="button"
          className={styles.btnPrimary}
          disabled
          title="El Directorio queda fuera del MVP"
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        {/* F-139: el motivo visible del botón deshabilitado (DIR-01 fuera del
            alcance). El nodo con el motivo lleva el testid, como pag-info. */}
        <span className={styles.scopeNote} data-testid="directorio-scope">
          fuera del MVP
        </span>
        {/* F-138: el contador lleva data-testid, no solo clase. */}
        {data && !error && (
          <span className={styles.threadCount} data-testid="pag-info">
            {data.total.toLocaleString('es-ES')} hilos · Página {page} de {totalPages}
          </span>
        )}
      </div>

      {error ? (
        <div role="alert" className={styles.errorBanner}>
          {error}
        </div>
      ) : loading && !data ? (
        <p className={styles.loading}>Cargando hilos…</p>
      ) : data ? (
        <>
          <ThreadList
            threads={data.threads}
            now={now}
            onOpen={() => {
              /* MSG-02 no existe en el MVP: abrir un hilo no lleva a ningún
                 sitio. onOpenThread se recibe y se ignora (F-118). */
            }}
          />
          <nav className={styles.pagination} aria-label="Paginación">
            <button
              type="button"
              className={`${styles.pageBtn} ${styles.pageCtrl}`}
              disabled={page <= 1}
              onClick={() => setPage(page - 1)}
            >
              ‹
            </button>
            {Array.from({ length: totalPages }, (_, i) => i + 1).map((p) => (
              <button
                key={p}
                type="button"
                className={`${styles.pageBtn} ${p === page ? styles.pageActive : ''}`}
                disabled={p === page}
                onClick={() => setPage(p)}
              >
                {p}
              </button>
            ))}
            <button
              type="button"
              className={`${styles.pageBtn} ${styles.pageCtrl}`}
              disabled={page >= totalPages}
              onClick={() => setPage(page + 1)}
            >
              ›
            </button>
          </nav>
        </>
      ) : null}
    </div>
  );
}

