.threadList {
  list-style: none;
  margin: 0;
  padding: 0;
  /* No hay token de blanco puro en §1.1: la superficie clara más cercana a la
     tarjeta blanca del HTML aprobado es --bw-surface-mist. */
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  border: none;
  border-bottom: 1px solid var(--bw-divider-mist);
  background: transparent;
  cursor: pointer;
  text-align: left;
  font: inherit;
  color: inherit;
}

li:last-child .row {
  border-bottom: none;
}

.row:hover {
  background: var(--bw-row-hover-tint);
}

.rowTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.org {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.countryBadge {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.rowTs {
  display: flex;
  align-items: center;
  justify-content: flex-end;
}

.ts {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.rowBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  flex: 1;
  font-size: 12px;
  color: var(--bw-steel-mist);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  flex-shrink: 0;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
}

.stateNeutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.stateInfo {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.stateWarn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.stateSuccess {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.stateClosed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* ── Estado vacío (F-128) ─────────────────────────────────────────────── */

.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 40px 18px;
  text-align: center;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
