.emptyBtn {
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  /* No hay token de blanco puro: la superficie clara más cercana. */
  color: var(--bw-cold-white);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  cursor: not-allowed;
  opacity: 0.55;
}

.emptyScope {
  font-size: 11px;
  color: var(--bw-input-placeholder);
}

