import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Recibe las filas ya cargadas (el orden es del servidor: actividad más
 * reciente primero) y avisa con el ID del hilo cuando se abre una fila. No
 * carga datos ni pagina: eso vive en `Messages`.
 *
 * ⚠ F-131: cada hilo va en un `<li>` y el `<li>` conserva su rol `listitem`.
 * La fila es pulsable gracias a un `<button>` DENTRO del `<li>` — nunca con un
 * `role="button"` encima, que sustituiría al rol implícito y rompería la
 * consulta de unidad. El botón es el que lleva el nombre accesible del hilo.
 */

const STATE_CLS: Record<StateTone, string> = {
  neutral: 'stateNeutral',
  info: 'stateInfo',
  warn: 'stateWarn',
  success: 'stateSuccess',
  closed: 'stateClosed',
};

interface Props {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj (F-137). */
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: Props) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para
          contactar con otras organizaciones.
        </p>
        {/* F-128: el estado vacío explica el motivo de que el botón esté
            apagado, igual que el botón de subida de INV-01 (F-023 e). */}
        <button
          type="button"
          className={styles.emptyBtn}
          disabled
          title="El Directorio queda fuera del MVP"
        >
          Ir al Directorio
        </button>
        <span className={styles.emptyScope}>fuera del MVP</span>
      </div>
    );
  }

  return (
    <ul className={styles.threadList}>
      {threads.map((t) => {
        const tone = stateTone(t.state);
        return (
          <li key={t.id}>
            <button
              type="button"
              className={styles.row}
              onClick={() => onOpen(t.id)}
            >
              <span className={styles.rowTop}>
                <span className={styles.org}>{t.counterpartyName}</span>
                <span className={styles.countryBadge}>{t.counterpartyCountry}</span>
              </span>
              <span className={styles.rowTs}>
                <span className={styles.ts}>{relativeTime(t.lastItemAt, now)}</span>
              </span>
              <span className={styles.rowBottom}>
                <span className={styles.preview}>{previewLabel(t.lastItem)}</span>
                <span className={`${styles.stateBadge} ${styles[STATE_CLS[tone]]}`}>
                  {t.state}
                </span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
